/* HUWiki AI Edition · independent scope, accessible touch targets */
.huw-ai-edition, .huw-ai-cover, .huwiki-ai-workbench, .huwiki-ai-chat-library {
 --huw-navy:#17284f;--huw-mid:#314978;--huw-teal:#0c9f91;--huw-cyan:#cefbf2;
 --huw-lavender:#eeebff;--huw-line:#d8e1ed;--huw-ink:#182444;
 color:var(--huw-ink);font-family:inherit;
}
.huw-ai-cover{max-width:1120px; margin:0 auto 24px;line-height:1.5}
.huw-ai-cover *, .huwiki-ai-workbench *, .huwiki-ai-chat-library * {box-sizing:border-box}
.huw-ai-hero {background:linear-gradient(126deg,#152749 0%,#263c71 60%,#266b7c 100%);color:#fff;
 border-radius:26px;padding:clamp(24px,5vw,52px);overflow:hidden;position:relative;margin:12px 0 22px;}
.huw-ai-hero::before{content:"";position:absolute;right:-100px;top:-125px;width:340px;height:340px;border:50px solid rgba(118,255,216,.09);border-radius:50%;pointer-events:none}
.huw-ai-hero .huw-ai-kicker{color:#a6f0dd;text-transform:uppercase;letter-spacing:.17em;font-size:.78em;font-weight:750}
.huw-ai-hero h1{font-size:clamp(2.2rem,5.5vw,4.4rem);font-weight:850;line-height:1.08;letter-spacing:-.035em;color:#fff!important;margin:14px 0;max-width:760px}
.huw-ai-hero p{font-size:clamp(1.05rem,2vw,1.27rem);color:#dceaf9;max-width:740px;margin:10px 0 28px}
.huw-ai-hero a{color:#f5fffe}
.huw-ai-pill{display:inline-flex;align-items:center;gap:7px;border:1px solid rgba(240,255,255,.36);background:rgba(255,255,255,.12);color:white;padding:6px 12px;border-radius:99px;font-size:.78em;margin-right:6px;margin-bottom:6px}
.huw-ai-btn,.huw-ai-cardlink{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:12px 18px;border-radius:13px;font-weight:750;text-decoration:none!important;line-height:1.22;transition:transform .14s,box-shadow .14s}
.huw-ai-btn:hover,.huw-ai-cardlink:hover{transform:translateY(-1px);box-shadow:0 5px 16px rgba(0,0,0,.13)}
.huw-ai-btn-primary{color:#143b39!important;background:#a5f0da}
.huw-ai-btn-light{color:#fff!important;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.35)}
.huw-ai-hero-actions,.huw-ai-inline-actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center}
.huw-ai-h2{font-size:1.75em;letter-spacing:-.025em;color:#17284f;margin:32px 0 6px}
.huw-ai-lead{font-size:1.08em;opacity:.72;margin-bottom:20px}
.huw-ai-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px;margin:18px 0 22px}
.huw-ai-grid-3{grid-template-columns:repeat(3,minmax(0,1fr))}
.huw-ai-tile{display:flex;flex-direction:column;background:#fff;border:1px solid var(--huw-line);border-radius:19px;padding:22px;min-width:0;box-shadow:0 7px 26px rgba(20,44,85,.035)}
.huw-ai-tile .huw-ai-glyph{font-size:1.7em;margin-bottom:10px}
.huw-ai-tile h3{font-size:1.15em;color:#17284f;margin:0 0 7px}
.huw-ai-tile p{font-size:.93em;color:#536381;margin:0 0 18px;flex:1}
.huw-ai-tile .huw-ai-cardlink{align-self:flex-start;background:#f0f5ff;color:#184675;border:1px solid #dfe8f8}
.huw-ai-step{counter-increment:steps;display:flex;gap:14px;align-items:flex-start;margin:14px 0}
.huw-ai-step::before{content:counter(steps);font-size:1.05em;font-weight:800;display:grid;place-items:center;min-width:37px;height:37px;border-radius:12px;background:#def5f0;color:#087264}
.huw-ai-steps{counter-reset:steps;margin:16px 0;padding:22px;border:1px solid var(--huw-line);border-radius:18px;background:#f7fafd}
.huw-ai-step strong{display:block;color:#182b52}
.huw-ai-step small{display:block;color:#596a83;font-size:.9em}
.huw-ai-note{border-radius:14px;background:#f0f7ff;color:#27445c;padding:14px 18px;border-left:4px solid #2d8398;margin:16px 0}
.huw-ai-header{padding:12px 20px;background:linear-gradient(120deg,#192e59,#385f75);border-radius:18px;color:#fff;margin:0 0 20px}
.huw-ai-header h2{font-size:1.65em;margin:4px 0 5px;color:#fff!important}
.huw-ai-header p{color:#e6f4ff;margin:0 0 8px}
.huw-ai-section-header h2{font-size:1.75em;letter-spacing:-.025em;color:#17284f;margin:2px 0 3px}
.huw-ai-section-header p{margin:0 0 18px}
.huw-ai-examples-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.huw-ai-example-card{background:#fff;border:1px solid #dce5ef;border-radius:15px;padding:18px}
.huw-ai-example-card h3{margin:4px 0;font-size:1.1em}
.huw-ai-example-card .huw-ai-cardlink{padding:7px 12px;min-height:40px}
.huw-ai-tag{font-size:.76em;font-weight:700;letter-spacing:.03em;padding:4px 9px;border-radius:99px;background:#e9f6f3;color:#087b6e}
.huw-ai-side{display:flex;flex-direction:column;gap:5px;font-size:.88em}
.huw-ai-side-heading{font-weight:850;color:#1b526d;padding:7px 8px;font-size:1.05em}
.huw-ai-side a{text-decoration:none!important;color:inherit;padding:9px 10px;border-radius:9px;display:block}
.huw-ai-side a:hover{background:rgba(46,124,153,.13)}
.huwiki-ai-workbench,.huwiki-ai-chat-library{width:100%;max-width:1060px;margin:0 auto;color:var(--huw-ink)}
.huwiki-ai-heading h2{font-size:1.55em;margin:0 0 5px;color:var(--huw-navy)}
.huwiki-ai-muted{color:#60708b;font-size:.9em}
.huwiki-ai-help{color:#576b86;font-size:.83em;line-height:1.5;margin:6px 0}
.huwiki-ai-card{border:1px solid #dbe3ee;border-radius:17px;padding:20px;margin:15px 0;background:#fff;min-width:0;box-shadow:0 4px 18px rgba(20,43,69,.03)}
.huwiki-ai-card h3{font-size:1.14em;color:var(--huw-navy);margin:0 0 12px}
.huwiki-ai-card h4{font-size:1em;margin:14px 0 8px}
.huwiki-ai-field{display:flex;flex-direction:column;gap:5px;margin:11px 0;min-width:0;width:100%}
.huwiki-ai-label{font-weight:720;color:#31456a;font-size:.87em}
.huwiki-ai-input,.huwiki-ai-textarea{display:block;width:100%;min-width:0;border:1px solid #bac8d9;border-radius:10px;background:white;color:#1d2c4a;padding:11px 12px;font:inherit;box-sizing:border-box}
.huwiki-ai-textarea{min-height:105px;line-height:1.5;resize:vertical}
.huwiki-ai-button{padding:10px 15px;min-height:44px;cursor:pointer;border:1px solid #b9cad8;background:#f8fbff;color:#25405f;border-radius:11px;font:inherit;font-weight:700}
.huwiki-ai-button.huw-ai-primary{background:#1d597b;color:#fff;border-color:#1d597b}
.huwiki-ai-button.huw-ai-secondary{background:white}
.huwiki-ai-button:disabled{opacity:.45;cursor:wait}
.huwiki-ai-button:focus-visible,.huwiki-ai-input:focus-visible,.huwiki-ai-textarea:focus-visible{outline:3px solid #67ccb6;outline-offset:2px}
.huwiki-ai-actions{display:flex;flex-wrap:wrap;gap:9px;margin:14px 0}
.huwiki-ai-message{padding:12px 16px;border-radius:11px;border-left:4px solid #229982;background:#edf9f4;color:#1a544b;white-space:pre-wrap}
.huwiki-ai-message.huw-ai-error{border-left-color:#cb4b43;background:#fff0f0;color:#88342e}
.huwiki-ai-proposal{border:1px solid #dbe3ef;border-radius:13px;margin:13px 0;padding:15px;background:#fbfdff}
.huwiki-ai-checkrow{display:flex;align-items:center;gap:9px;font-weight:730;cursor:pointer;padding:4px 0}
.huwiki-ai-checkrow input,.huw-ai-inline-actions input[type=checkbox]{width:19px;height:19px;flex:none}
.huwiki-ai-tag-card{border-top:1px solid #d6deeb;padding:12px 0}
.huwiki-ai-history-row{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;padding:8px 0;border-top:1px solid #dce3ed}
.huwiki-ai-summary-text{white-space:pre-wrap}
.huw-ai-chat-layout{display:grid;grid-template-columns:minmax(210px,30%) minmax(0,1fr);gap:17px;align-items:start;margin-top:14px}
.huw-ai-chat-index{padding:15px;border:1px solid #dbe4ee;border-radius:16px;background:#f8fbff;max-height:650px;overflow:auto}
.huw-ai-chat-link{display:block;text-align:left;width:100%;margin:6px 0;background:white;border-color:#dde7ee;font-size:.87em}
.huw-ai-chat-active{background:#e2f5f1!important;border-color:#4ac6ae!important}
.huw-ai-chat-main{border:1px solid #dbe4ee;border-radius:16px;background:#fff;min-height:480px;padding:17px;min-width:0}
.huw-ai-chat-title h3{font-size:1.28em;color:#192e52;margin:0}
.huw-ai-chat-stream{max-height:640px;overflow:auto;display:flex;flex-direction:column;gap:12px;margin:19px 0}
.huw-ai-bubble{max-width:95%;padding:14px 16px;border-radius:16px;background:#f0f5fc;white-space:pre-wrap;overflow-wrap:anywhere}
.huw-ai-user{align-self:flex-end;background:#e0f7f0}
.huw-ai-bubble-label{font-size:.76em;font-weight:800;color:#42627d;text-transform:uppercase;letter-spacing:.09em}
.huw-ai-bubble-text{white-space:pre-wrap;margin:7px 0;line-height:1.5}
.huw-ai-chat-composer{padding:14px;background:#f6faff;border-radius:15px;border:1px solid #e0e9f3}
.huw-ai-import-list{max-height:340px;overflow:auto;border:1px solid #d5e0eb;border-radius:10px;padding:8px}
.huw-ai-import-item{display:flex;gap:11px;align-items:flex-start;padding:12px 8px;border-bottom:1px solid #e7edf5;cursor:pointer}
.huw-ai-import-item input{width:20px;height:20px;flex:none}
.huw-ai-import-item strong{display:block}
.huw-ai-import-item .huwiki-ai-help{word-break:break-word}
.huw-ai-hidden{display:none!important}
.huw-ai-proposal-item{padding:18px;background:#f7fafc;border:1px solid #dbe3ee;border-radius:14px;margin:13px 0}
.huw-ai-warning{color:#933e2c;background:#fff4ee;padding:9px;border-radius:8px}
@media(max-width:820px){.huw-ai-grid-3{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:670px){.huw-ai-grid,.huw-ai-grid-3,.huw-ai-examples-list,.huw-ai-chat-layout{grid-template-columns:1fr}.huw-ai-chat-index{max-height:280px}.huw-ai-hero{border-radius:15px}.huw-ai-tile{padding:18px}.huwiki-ai-card{padding:14px}}

/* Onboarding for personal cloud API access – usable on iPad and desktop */
.huw-ai-provider-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:18px 0 22px}
.huw-ai-provider-card{background:#fff;border:1px solid #dce5ef;border-radius:17px;padding:19px;min-width:0;box-shadow:0 6px 22px rgba(20,44,85,.04)}
.huw-ai-provider-card h3{font-size:1.14em;color:#17284f;margin:8px 0 5px}
.huw-ai-provider-card p{font-size:.9em;color:#50617c;line-height:1.5;min-height:65px}
.huw-ai-provider-mark{width:40px;height:40px;display:grid;place-items:center;border-radius:12px;background:#e4f8f2;color:#095e59;font-size:1.2em;font-weight:850}
.huw-ai-key-guide{background:#f6fafc;border:1px solid #d5e7ef;padding:16px;border-radius:14px;margin:12px 0}
.huw-ai-key-heading{display:block;color:#1c385a;font-size:1.02em}
.huw-ai-key-link{display:inline-flex;align-items:center;min-height:44px;background:#1d597b;color:white!important;border-radius:10px;padding:9px 13px;max-width:100%;font-weight:700;text-decoration:none!important;box-sizing:border-box}
.huw-ai-key-link:focus-visible,.huw-ai-provider-card a:focus-visible{outline:3px solid #63c9b5;outline-offset:2px}
.huw-ai-key-url{overflow-wrap:anywhere;word-break:break-word;color:#62738b;font:0.76em/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;padding-top:8px;user-select:text}
@media(max-width:820px){.huw-ai-provider-grid{grid-template-columns:1fr}.huw-ai-provider-card p{min-height:0}}

/* v0.2.2 – message-level progress, safe fenced code tools, draft creation */
.huw-ai-chat-stream {scroll-behavior:smooth;overscroll-behavior:contain}
.huw-ai-bubble-text {white-space:normal}
.huw-ai-prose-line{white-space:pre-wrap;min-height:1em;overflow-wrap:anywhere}
.huw-ai-prose-heading{font-size:1.08em;line-height:1.25;margin:12px 0 5px}
.huw-ai-code-panel{margin:12px 0 14px;border:1px solid #cbd9e5;border-radius:11px;overflow:hidden;background:#f8fafc}
.huw-ai-code-toolbar{display:flex;justify-content:space-between;align-items:center;gap:9px;padding:7px 10px;background:#e9f0f7;font-size:.82em;font-weight:750}
.huw-ai-code-toolbar button{min-height:37px;padding:7px 11px;font-size:1em}
.huw-ai-code-panel pre{white-space:pre;overflow-x:auto;margin:0;padding:13px 16px;max-width:100%;line-height:1.45;font-size:.87em;color:#203048}
.huw-ai-bubble-actions{display:flex;flex-wrap:wrap;gap:7px;margin-top:12px}
.huw-ai-bubble-actions button{min-height:39px;font-size:.82em;padding:7px 10px}
.huw-ai-pending{border:2px solid #3a9a94;background:#edfaf7;align-self:flex-start}
.huw-ai-pending strong{display:block;margin:9px 0}
.huw-ai-pending .huw-ai-wait-seconds{display:inline;font-variant-numeric:tabular-nums}
.huw-ai-wait-timer{color:#226a62;font-weight:650}
.huw-ai-response-error{border:2px solid #d6a09a;background:#fff5f3}
.huw-ai-connection-fix{border:1px solid #aac9d6;border-radius:13px;padding:14px;margin:12px 0;background:#f4fbff}
.huw-ai-connection-fix p{margin:7px 0}
.huw-ai-tiddler-dialog{border:2px solid #2f8186;background:#fff}
.huw-ai-select-piece{display:flex;align-items:flex-start;gap:10px;border-bottom:1px solid #e0e7ef;padding:9px 0;cursor:pointer;font-size:.88em;overflow-wrap:anywhere}
.huw-ai-select-piece input{width:21px;height:21px;flex-shrink:0}
.huw-ai-result-preview{min-height:110px;padding:14px;background:#f7fafc;border:1px solid #dce5ea;border-radius:11px;overflow:auto}
.huw-ai-preview-frame{width:100%;height:290px;border:0;background:white}
.huw-ai-result-preview .huw-ai-prose-line{margin:0}
@media(max-width:670px){.huw-ai-tiddler-dialog{padding:12px}.huw-ai-code-toolbar{flex-wrap:wrap}}

.huw-ai-chat-title .huw-ai-jump{font-size:.8em;min-height:35px;padding:6px 10px;margin-top:6px}

/* v0.2.3 – in-context connection setup and selective ChatGPT import */
.huw-ai-connection-status{border:1px solid #c9dee5;background:#f3fbfc;border-radius:17px;padding:17px;margin:20px 0;min-width:0}
.huw-ai-connection-status .huw-ai-connection-title{font-size:1.06em;color:#1a3c61;margin-bottom:8px}
.huw-ai-connection-picker,.huw-ai-chat-picker{display:flex;flex:1 1 220px;flex-direction:column;gap:4px;min-width:0}
.huw-ai-chat-connection{border:1px solid #bbd9e1;border-radius:12px;background:#f1fbfd;padding:13px;margin:10px 0}
.huw-ai-chat-connection .huw-ai-inline-actions{margin:7px 0}
.huw-ai-ready{color:#0b5e52;font-weight:700}
.huw-ai-import-messages{max-height:280px;overflow:auto;margin-top:7px;background:#f6f9fc;border-radius:9px;padding:6px}
.huw-ai-import-message{display:flex;gap:9px;align-items:start;padding:8px 4px;border-bottom:1px solid #dee8ee;font-size:.86em;white-space:pre-wrap;overflow-wrap:anywhere}
.huw-ai-import-message input{width:19px;height:19px;flex-shrink:0}
.huw-ai-step a{display:inline-flex;margin-top:10px;min-height:42px;align-items:center}
.huw-ai-chat-connection select{min-width:0}

/* v0.2.5 – screenshots directly in AI composer */
.huw-ai-attachments{display:flex;flex-wrap:wrap;gap:12px;margin:10px 0}
.huw-ai-attachment{display:flex;align-items:center;gap:9px;padding:8px;border:1px solid #bedbd8;border-radius:12px;background:#fff;min-width:0;max-width:100%;flex-wrap:wrap}
.huw-ai-attachment img,.huw-ai-message-photo{width:106px;max-width:100%;max-height:110px;object-fit:contain;border-radius:7px;border:1px solid #cdd6e0;background:#fff}
.huw-ai-message-photo{display:block;margin:8px 0;width:auto;max-width:250px;max-height:200px}
.huw-ai-drop-active{outline:3px dashed #218d91;outline-offset:2px}
.huw-ai-chat-composer .huwiki-ai-textarea{font-size:16px}

.huw-ai-cloud-disclosure{font-size:.86em;color:#6c431d;background:#fff4de;padding:9px;border-radius:8px}

/* v0.2.5 – honest latency metrics and screenshot detail controls */
.huw-ai-image-mode{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:9px 0}
.huw-ai-image-mode select{width:auto;max-width:100%;min-width:170px}
.huw-ai-chat-metrics{font-size:.8em;margin:12px 0 3px;padding:7px 9px;border-top:1px solid #cdd9e4;color:#344e63;overflow-wrap:anywhere}
.huw-ai-chat-metrics small{display:block;margin-top:4px;color:#526a78;font-size:.98em}


.huw-ai-output-image{margin:12px 0;padding:12px;border:1px solid #d7e2ec;border-radius:12px;max-width:100%;box-sizing:border-box}
.huw-ai-output-image img,.huw-ai-image-save-preview{display:block;max-width:100%;max-height:360px;width:auto;height:auto;object-fit:contain;margin:0 auto 12px}
.huw-ai-output-image iframe{display:block;width:100%;height:360px;border:0;border-radius:8px;margin-bottom:10px}
.huw-ai-tiddler-dialog{max-height:85vh;overflow:auto;box-sizing:border-box}

/* AI Edition 0.3.0: compact conversation register */
.huw-ai-chat-index{position:sticky;top:12px;max-height:none;padding:12px}
.huw-ai-register-new{width:100%}.huw-ai-register-list{max-height:50vh;overflow:auto;overscroll-behavior:contain}
.huw-ai-chat-link strong,.huw-ai-chat-link small{display:block;overflow-wrap:anywhere}
.huw-ai-chat-link small{font-size:.82em;font-weight:normal;margin-top:3px;color:#496274}
.huw-ai-chat-index h3{margin:0 0 10px}.huw-ai-register-group{font-size:.9em;margin:14px 0 5px}
.huw-ai-chat-details{padding:12px;border:1px solid #cbdce8;border-radius:10px;margin:10px 0;background:#f8fbff}
.huw-ai-chat-main{min-height:250px;padding:14px}.huw-ai-chat-title{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.huw-ai-chat-title h3{width:100%;overflow-wrap:anywhere}.huw-ai-chat-stream{max-height:48vh;min-height:72px;margin:12px 0}
.huw-ai-connection-details{margin:12px 0}.huw-ai-connection-details summary{cursor:pointer;font-weight:600;overflow-wrap:anywhere}
.huw-ai-chat-composer{padding:10px}.huw-ai-chat-composer .huwiki-ai-textarea{min-height:85px}
.huw-ai-bubble-text h1,.huw-ai-bubble-text h2{font-size:1.25em}.huw-ai-wiki-link{color:#156c8b;text-decoration:underline}
@media(max-width:670px){.huw-ai-chat-index{position:static}.huw-ai-register-list{max-height:220px}.huw-ai-chat-stream{max-height:44vh}}
